typedef CGAL::Simple_cartesian<double> K;
typedef K::Point_3 CGALPoint;
typedef CGAL::Bbox_3 CGALBoundingBox;

CGALBoundingBox cgal_bbox(
    b.minX(), b.minY(), b.minZ(),
    b.maxX(), b.maxY(), b.maxZ()
);

// Use the tree's built-in query with CGAL's bbox
std::list<cg3::cgal::AABBTree3::Tree::Primitive_id> primitives;
tree.tree.all_intersected_primitives(std::back_inserter(primitives), cgal_bbox);

// Count the triangles that are completely contained
int count = 0;
for (const auto& primitive : primitives) {
    // Check if the triangle is completely inside the bounding box
    const auto& triangle = primitive->datum();
    const auto& p1 = triangle[0];
    const auto& p2 = triangle[1];
    const auto& p3 = triangle[2];

    if (b.isInside(cg3::Point3d(p1.x(), p1.y(), p1.z())) &&
        b.isInside(cg3::Point3d(p2.x(), p2.y(), p2.z())) &&
        b.isInside(cg3::Point3d(p3.x(), p3.y(), p3.z()))) {
        count++;
    }
}

return count;

